#ifdef USECGAL

#include <iostream>
#include <fstream>
#include <string>
#include <cmath>

//User defined header files
#include "cgal_domain_polyhedra.h"

// System namespace
using namespace std;
using namespace CGAL::parameters;

cgal_domain_polyhedra::cgal_domain_polyhedra(){
}

cgal_domain_polyhedra::~cgal_domain_polyhedra(){

}

// initialize domain
void cgal_domain_polyhedra::initialize(){
	setDefaultParameters();
	return;
}

// Set 3d mesh generation input file and output file, with default mesh criteria
// Variables description:
//   strFileIn: input mesh frame file name in 'off' format
//   strFileOut: output mesh file name in 'mesh' format
//
void cgal_domain_polyhedra::setInputOutputFile(const std::string strFileIn,const std::string strFileOut){
	strfile_domain_input = strFileIn;
	strfile_mesh_surface = strFileIn+".tri";
	strfile_mesh_output = strFileOut;
}

// Set domain mesh criteria
void cgal_domain_polyhedra::setDomainCriteria(const double edgeSize,
		const double facetAngle, const double facetSize,
		const double facetDistance, const double cellRadiusEdgeRatio,
		const double globalSize){
	criteriaEdgeSize = edgeSize;
	criteriaFacetAngle = facetAngle;
	criteriaFacetSize = facetSize;
	criteriaFacetDistance = facetDistance;
	criteriaCellRadiusEdgeRatio = cellRadiusEdgeRatio;
	critieriaGlobalSize = globalSize;
}

// Override function make surface mesh to off
void cgal_domain_polyhedra::makeDomainSurfaceMesh(){
	int iflag = makeSurfaceMeshToOff(strfile_domain_input, strfile_mesh_surface);
	return;
}

void cgal_domain_polyhedra::makeDomainPolyhedron(){
	int iflag = makePolyhedron(strfile_mesh_surface);
	return;
}

// Optimization parameters of Lloyd
void cgal_domain_polyhedra::setOptParametersLloyd(const int maxIteration,
		const double timeLimit){
	maxIterationLloyd = maxIteration;
	timeLimitLloyd = timeLimit;
}

// Optimization parameters of Exude
void cgal_domain_polyhedra::setOptParametersExude(const double sliverBound,
		const double timeLimit){
	sliverBoundExude = sliverBound;
	timeLimitExude = timeLimit;
}

// Optimization parameters of Perturb
void cgal_domain_polyhedra::setOptParametersPerturb(const double silverBound,
		const double timeLimit){
	sliverBoundPerturb = silverBound;
	timeLimitPerturb = timeLimit;
}


// Make and output mesh
void cgal_domain_polyhedra::makeOutputMesh(const std::string strMeshFormat){

	// Create domain
	Mesh_domain mesh_domain(strfile_mesh_surface);

	// Get sharp features
	mesh_domain.detect_features();

	Mesh_criteria mesh_criteria(edge_size = criteriaEdgeSize,
			facet_angle = criteriaFacetAngle,
			facet_size = criteriaFacetSize,
			facet_distance = criteriaFacetDistance,
			cell_radius_edge_ratio = criteriaCellRadiusEdgeRatio,
			cell_size = critieriaGlobalSize);

	// Make mesh using default setting, without optimization
	C3t3 mesh_c3t3 = CGAL::make_mesh_3<C3t3>(mesh_domain, mesh_criteria, no_perturb(), no_exude());

	// Optional, Optimize 3d mesh using lloyd_optimize_mesh_3 method
	CGAL::lloyd_optimize_mesh_3(mesh_c3t3, mesh_domain,
			max_iteration_number = maxIterationLloyd, time_limit=timeLimitLloyd);

	// Optimize 3d mesh using exude_mesh_3 method
	CGAL::exude_mesh_3(mesh_c3t3, sliver_bound=sliverBoundExude,time_limit=timeLimitExude);

	// Optimize 3d mesh using perturb_mesh_3 method
	CGAL::perturb_mesh_3(mesh_c3t3, mesh_domain, sliver_bound=sliverBoundPerturb,
			time_limit=timeLimitPerturb);

	// Get mesh information
	const Tr& tr = mesh_c3t3.triangulation();
    // number of vertices
	mesh_vertices_counter = 0;
    for(Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
    		vit!=tr.finite_vertices_end();vit++){
    	mesh_vertices_counter = mesh_vertices_counter + 1;
    }

	//Number of edges
	mesh_edges_counter = 0;
    for(Tr::Finite_edges_iterator eit=tr.finite_edges_begin();
    		eit!=tr.finite_edges_end();eit++){
		mesh_edges_counter = mesh_edges_counter + 1;
	}

	//Number of faces
	mesh_faces_counter = 0;
    for(Tr::Finite_facets_iterator fit=tr.finite_facets_begin();
    		fit!=tr.finite_facets_end();fit++){
    	mesh_faces_counter = mesh_faces_counter + 1;
	}

	//Number of surface faces
	mesh_surface_faces_counter = 0;
	for (C3t3::Facets_in_complex_iterator
				fit = mesh_c3t3.facets_in_complex_begin();
				fit != mesh_c3t3.facets_in_complex_end();fit++){
		mesh_surface_faces_counter = mesh_surface_faces_counter + 1;
	}

	//Number of cells
	mesh_cells_counter = 0;
	for (C3t3::Cells_in_complex_iterator
			cit = mesh_c3t3.cells_in_complex_begin();
			cit != mesh_c3t3.cells_in_complex_end();cit++){
		mesh_cells_counter = mesh_cells_counter + 1;
	}

	// Output mesh
	if (strMeshFormat == "mesh"){
		std::ofstream medit_file(strfile_mesh_output);
		mesh_c3t3.output_to_medit(medit_file);
		medit_file.close();
	}
	else {
		// Vertices list with index
		std::map<Point3d, int> map_vts;

		//Note: index in off file is 0-based and msh file format is 1-based
		int icell = 0;
		int ivertex = 0;
		int ishift = 0;
		int ncells = 0;

		// Open file
		std::ofstream out;
		out.open(strfile_mesh_output);

        // Create vertex index
		for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
				vit!=tr.finite_vertices_end();vit++){
			Point3d pt = vit->point();
			map_vts[pt] = ivertex;
			ivertex = ivertex + 1;
		}

		if (strMeshFormat == "off"){

			// Note: index in off file format is 0-based
			ishift = 0;

			// Write header
			out << "OFF" << endl;

			//Off file head information
			out << mesh_vertices_counter << " "
				<< mesh_cells_counter << " 0 " << endl;

	        // Write vertex
			for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
					vit!=tr.finite_vertices_end();vit++){
				Point3d pt = vit->point();
				out << pt.x() << " " << pt.y() << " " << pt.z() << endl;
			}
			// Write cells
			for (C3t3::Cells_in_complex_iterator
					cit = mesh_c3t3.cells_in_complex_begin();
					cit != mesh_c3t3.cells_in_complex_end();cit++){
				Point3d pt0 = cit->vertex(0)->point();
				Point3d pt1 = cit->vertex(1)->point();
				Point3d pt2 = cit->vertex(2)->point();
				Point3d pt3 = cit->vertex(3)->point();
				out << "4 " << map_vts[pt0]+ishift << " " << map_vts[pt1]+ishift
					<< " " << map_vts[pt2]+ishift << " " << map_vts[pt3]+ishift << " " << endl;
			}
		}
		else if (strMeshFormat == "msh"){
			// Note: index in msh file format is 1-based
			ishift = 1;

			// Write header
			out << "$MeshFormat" << endl;
			out << "2.2 0 8" << endl;
			out << "$EndMeshFormat" << endl;
			// Write nodes/vertices
			out << "$Nodes" << endl;
			out << mesh_vertices_counter << endl;
			// Write vertex
			for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
					vit!=tr.finite_vertices_end();vit++){
				Point3d pt = vit->point();
				out << map_vts[pt] + ishift << " " << pt.x() << " " << pt.y() << " " << pt.z() << endl;
			}
			out << "$EndNodes" << endl;

			// Write elements/cells
			out << "$Elements" << endl;
			out << mesh_cells_counter << endl;
			for (C3t3::Cells_in_complex_iterator
					cit = mesh_c3t3.cells_in_complex_begin();
					cit != mesh_c3t3.cells_in_complex_end();cit++){
				Point3d pt0 = cit->vertex(0)->point();
				Point3d pt1 = cit->vertex(1)->point();
				Point3d pt2 = cit->vertex(2)->point();
				Point3d pt3 = cit->vertex(3)->point();
				ncells = ncells + 1;
				//Write 4-node triangles, number of tags are set to 2 with tag value 0, hardwired
				out << ncells << " 4 2 0 0 " << map_vts[pt0]+ishift << " "
					<< map_vts[pt1]+ishift << " " << map_vts[pt2]+ishift
					<< " " << map_vts[pt3]+ishift << " " << endl;
			}
			out << "$EndElements" << endl;
		}
		else if (strMeshFormat == "vtk"){
			//Note: index in vtk file format is 0-based
			// Output the mesh to file

			// Write header
			out << "# vtk DataFile Version 2.0" << endl;
			out << "CGAL polyhedra mesh generation 3d" << endl;
			out << "ASCII" << endl;
			out << "DATASET UNSTRUCTURED_GRID" << endl;

			// Write nodes/vertices
			out << "POINTS " << mesh_vertices_counter << " double" << endl;

			// Write vertex
			for (Tr::Finite_vertices_iterator vit=tr.finite_vertices_begin();
					vit!=tr.finite_vertices_end();vit++){
				Point3d pt = vit->point();
				out << pt.x() << " " << pt.y() << " " << pt.z() << endl;
			}
			out << endl;

			// Write elements/cells
			out << "CELLS " << mesh_cells_counter << " " << mesh_cells_counter*5 << endl;

			for (C3t3::Cells_in_complex_iterator
					cit = mesh_c3t3.cells_in_complex_begin();
					cit != mesh_c3t3.cells_in_complex_end();cit++){
				Point3d pt0 = cit->vertex(0)->point();
				Point3d pt1 = cit->vertex(1)->point();
				Point3d pt2 = cit->vertex(2)->point();
				Point3d pt3 = cit->vertex(3)->point();
				ncells = ncells + 1;
				//Write 4-node triangles, number of tags are set to 2 with tag value 0, hardwired
				out << "4 " << map_vts[pt0] << " " << map_vts[pt1] << " "
						<< map_vts[pt2]	<< " " << map_vts[pt3] << " " << endl;
			}
			out << endl;

			// Write cell type
			out << "CELL_TYPES " << mesh_cells_counter << endl;

		    for (int icell = 0; icell < ncells; icell++){
		   	  out << "10" << endl;
		    }
			out << endl;
		}
        // Close file
        out.close();
	}
}

// Get input domain file
std::string cgal_domain_polyhedra::getInputDomainFile(){
	return strfile_domain_input;
}

// Get surface mesh file
std::string cgal_domain_polyhedra::getSurfaceMeshFile(){
	return strfile_mesh_surface;
}

// Get mesh file
std::string cgal_domain_polyhedra::getMeshFile(){
	return strfile_mesh_output;
}

// Set default image parameters
void cgal_domain_polyhedra::setDefaultParameters(){
	// Mesh criteria
	criteriaFacetAngle = 25.0;
	criteriaFacetSize = 0.0;
	criteriaFacetDistance = 0.0;
	criteriaCellRadiusEdgeRatio = 3.0;
	critieriaGlobalSize = 0.0;
	// Optimization parameters
	maxIterationLloyd = 0;
	timeLimitLloyd = 0.0;
	sliverBoundExude = 10.0;
	timeLimitExude = 0.0;
	sliverBoundPerturb = 10.0;
	timeLimitPerturb = 0.0;
}

#endif
